-- Name: chat_events trg_chat_event_create_match; Type: TRIGGER; Schema: public; Owner: footballhome_user
--

CREATE TRIGGER trg_chat_event_create_match AFTER INSERT ON public.chat_events FOR EACH ROW EXECUTE FUNCTION public.chat_event_create_match();


--
-- Name: chat_events trg_chat_event_sync_match; Type: TRIGGER; Schema: public; Owner: footballhome_user
--

CREATE TRIGGER trg_chat_event_sync_match AFTER UPDATE ON public.chat_events FOR EACH ROW WHEN ((((new.title)::text IS DISTINCT FROM (old.title)::text) OR (new.event_date IS DISTINCT FROM old.event_date) OR (new.event_time IS DISTINCT FROM old.event_time) OR (new.start_at IS DISTINCT FROM old.start_at))) EXECUTE FUNCTION public.chat_event_sync_match();


